refentry.refsect1:
&reftitle.description;

 boolis_callable
 mixedvalue
 boolsyntax_only&false;
 stringcallable_name&null;



 Verifica che value sia un callable,
 o che possa essere chiamato utilizzando la funzione
 call_user_func.

&reftitle.returnvalues;


 Restituisce &true; se value è callable, &false;
 in caso contrario.

  &reftitle.examples;



    Verifica se una stringa può essere chiamata come una funzione


<?php

function someFunction() {}

$functionVariable = 'someFunction';

var_dump(is_callable($functionVariable, false, $callable_name));

var_dump($callable_name);

?>


    &example.outputs;


bool(true)
string(12) "someFunction"




    Verifica se un array può essere chiamato come una funzione


<?php

class SomeClass
{
    public function someMethod() {}
}

$anObject = new SomeClass();

$methodVariable = [$anObject, 'someMethod'];

var_dump(is_callable($methodVariable, true, $callable_name));

var_dump($callable_name);

?>


    &example.outputs;


bool(true)
string(21) "SomeClass::someMethod"




    is_callable e i costruttori

     Nonostante i costruttori siano i metodi che vengono chiamati quando
     viene creato un oggetto, essi non sono metodi statici e
     is_callable restituirà &false; per essi. Non è
     possibile usare is_callable per verificare se una classe può
     essere istanziata dall'ambito corrente.



<?php

class Foo
{
    public function __construct() {}

    public function foo() {}
}

var_dump(
    is_callable(['Foo', '__construct']),
    is_callable(['Foo', 'foo'])
);

$foo = new Foo();
var_dump(is_callable([$foo, '__construct']));

?>


    &example.outputs;


bool(false)
bool(false)
bool(true)
